/* Aggregate traffic only. This module never reads or sends question answers, scores or personality types. */
(function(global){
  'use strict';
  const doc=global.document;if(!doc)return;
  const KEY='gj-traffic-visible-v1',LOCK='gj-traffic-visit-lock-v1',PUBLIC_HOST='gua-jian-self-64.pages.dev';
  const url=new URL(global.location.href),qa=url.searchParams.has('qa'),eligible=url.hostname===PUBLIC_HOST&&!qa;
  const endpoint='./api/traffic'+(qa?'?qa=i18n-v2':'');
  // title, visits, engaged, completed, disclosure link, unavailable, privacy heading, privacy body.
  const copy={
    'zh-Hant':['網站累計統計','來訪客數','停留滿一分鐘','完成測驗的訪客','匿名計數說明','統計暫時無法讀取','不用帳號，不詢問姓名或電子郵件','測驗不詢問姓名、電子郵件或生日，也不設廣告。網站使用有效期 365 天的隨機 Cookie 識別瀏覽器，彙總到訪、前景停留累計滿 60 秒及完成探索的瀏覽器數。每項每個瀏覽器計一次，包含全選中間選項後完成；不儲存或傳送逐題答案、分數、人格類型、姓名或 IP。清除 Cookie 或使用另一裝置可能再次計數，這些數字不代表精確人數。清除作答紀錄不會撤回已彙總的統計。'],
    'zh-Hans':['网站累计统计','来访客数','停留满一分钟','完成测验的访客','匿名计数说明','统计暂时无法读取','无需账号，不询问姓名或电子邮件','测验不询问姓名、电子邮件或生日，也不设广告。网站使用有效期 365 天的随机 Cookie 识别浏览器，汇总到访、前台停留累计满 60 秒及完成探索的浏览器数。每项每个浏览器计一次，包含全选中间选项后完成；不存储或发送逐题答案、分数、人格类型、姓名或 IP。清除 Cookie 或使用另一设备可能再次计数，这些数字不代表精确人数。清除答题记录不会撤回已汇总的统计。'],
    en:['Lifetime website totals','Visitors','Stayed one minute','Visitors who completed a test','About anonymous counts','Counts are temporarily unavailable','No account, name or email required','The exploration asks for no name, email or birthday and contains no advertising. A random browser cookie lasting 365 days supports aggregate counts of visits, 60 seconds accumulated with the page visible, and completed explorations. Each milestone counts once per browser, including a completed all-neutral exploration. No answers, scores, personality types, names or IP addresses are stored or sent by this counter. Clearing cookies or using another device can count again, so these are not exact people counts. Clearing answers does not reverse existing aggregate counts.'],
    ja:['サイトの累計','訪問者','1分以上滞在','テストを終えた訪問者','匿名集計について','集計を一時的に読み込めません','アカウントも氏名もメールも不要','氏名、メールアドレス、誕生日は尋ねず、広告も表示しません。有効期間365日のランダムなCookieでブラウザーを区別し、訪問、画面が表示された状態で累計60秒、探索完了を集計します。各項目はブラウザーごとに一度だけ数え、中間の選択肢だけで完了した場合も含みます。この集計は回答、得点、人格タイプ、氏名、IPを保存・送信しません。Cookieの削除や別の端末では再計上されるため、正確な人数ではありません。回答の削除では集計済みの数値は変わりません。'],
    ko:['사이트 누적 통계','방문자','1분 이상 머문 방문자','테스트를 마친 방문자','익명 집계 안내','통계를 일시적으로 불러올 수 없습니다','계정이나 이름, 이메일이 필요하지 않습니다','이름, 이메일, 생일을 묻지 않으며 광고도 표시하지 않습니다. 365일 동안 유효한 무작위 Cookie로 브라우저를 구분하여 방문, 화면이 보이는 상태의 누적 60초, 탐색 완료를 집계합니다. 각 항목은 브라우저마다 한 번만 세며 모든 답을 중간 항목으로 선택하고 완료한 경우도 포함합니다. 이 집계는 답변, 점수, 성격 유형, 이름 또는 IP를 저장하거나 전송하지 않습니다. Cookie를 지우거나 다른 기기를 사용하면 다시 집계될 수 있으므로 정확한 사람 수는 아닙니다. 답변을 지워도 이미 집계된 수치는 취소되지 않습니다.'],
    hi:['वेबसाइट के कुल आँकड़े','आगंतुक','एक मिनट रुके','परीक्षण पूरा करने वाले आगंतुक','अनाम गणना के बारे में','आँकड़े अभी उपलब्ध नहीं हैं','खाते, नाम या ईमेल की ज़रूरत नहीं','इस खोज में नाम, ईमेल या जन्मदिन नहीं पूछा जाता और विज्ञापन नहीं हैं। 365 दिनों की अवधि वाली एक यादृच्छिक Cookie ब्राउज़र की पहचान करती है। हम आने वाले ब्राउज़र, दिखाई दे रहे पृष्ठ पर कुल 60 सेकंड और पूरी हुई खोजों की समेकित गणना करते हैं। प्रत्येक चरण प्रति ब्राउज़र एक बार गिना जाता है; सभी मध्य विकल्प चुनकर पूरी की गई खोज भी शामिल है। यह गणना उत्तर, अंक, व्यक्तित्व प्रकार, नाम या IP को सहेजती या भेजती नहीं है। Cookie हटाने या दूसरा उपकरण इस्तेमाल करने पर दोबारा गणना हो सकती है, इसलिए ये सटीक व्यक्तियों की संख्या नहीं हैं। उत्तर मिटाने से पहले से बने कुल आँकड़े नहीं बदलते।'],
    th:['สถิติสะสมของเว็บไซต์','ผู้เข้าชม','อยู่ครบหนึ่งนาที','ผู้เข้าชมที่ทำแบบทดสอบเสร็จ','เกี่ยวกับการนับแบบไม่ระบุตัวตน','ยังไม่สามารถอ่านสถิติได้','ไม่ต้องมีบัญชี ชื่อ หรืออีเมล','การสำรวจนี้ไม่ถามชื่อ อีเมล หรือวันเกิด และไม่มีโฆษณา เราใช้ Cookie แบบสุ่มที่มีอายุ 365 วันเพื่อแยกเบราว์เซอร์ และนับยอดรวมของการเข้าชม การเปิดหน้าจอไว้ให้เห็นสะสมครบ 60 วินาที และการสำรวจเสร็จ แต่ละรายการนับครั้งเดียวต่อเบราว์เซอร์ รวมถึงการเลือกคำตอบกลางทุกข้อแล้วทำจนเสร็จ ตัวนับนี้ไม่เก็บหรือส่งคำตอบ คะแนน ประเภทบุคลิกภาพ ชื่อ หรือ IP การลบ Cookie หรือเปลี่ยนอุปกรณ์อาจทำให้นับใหม่ จึงไม่ใช่จำนวนบุคคลที่แม่นยำ การลบคำตอบไม่ย้อนลบยอดที่รวมไว้แล้ว'],
    id:['Total kunjungan situs','Pengunjung','Tinggal satu menit','Pengunjung yang menyelesaikan tes','Tentang hitungan anonim','Statistik sementara tidak tersedia','Tanpa akun, nama, atau email','Eksplorasi ini tidak meminta nama, email, atau tanggal lahir dan tidak menampilkan iklan. Cookie acak yang berlaku selama 365 hari membedakan peramban untuk menghitung kunjungan, akumulasi 60 detik saat halaman terlihat, dan eksplorasi yang selesai. Setiap pencapaian dihitung sekali per peramban, termasuk eksplorasi yang selesai dengan semua jawaban tengah. Penghitung ini tidak menyimpan atau mengirim jawaban, skor, tipe kepribadian, nama, atau IP. Menghapus Cookie atau memakai perangkat lain dapat dihitung lagi, sehingga angka ini bukan jumlah orang yang pasti. Menghapus jawaban tidak mengubah total yang sudah dihitung.'],
    de:['Gesamtzahlen der Website','Besucher','Eine Minute geblieben','Besucher mit abgeschlossenem Test','Zur anonymen Zählung','Statistik derzeit nicht verfügbar','Kein Konto, Name oder E-Mail nötig','Die Erkundung fragt weder nach Namen noch nach E-Mail oder Geburtstag und enthält keine Werbung. Ein zufälliges Cookie mit 365 Tagen Laufzeit unterscheidet Browser. Gezählt werden Besuche, insgesamt 60 Sekunden bei sichtbarer Seite und abgeschlossene Erkundungen. Jeder Meilenstein zählt einmal pro Browser, auch eine vollständig neutral beantwortete Erkundung. Dieser Zähler speichert oder überträgt keine Antworten, Punktzahlen, Persönlichkeitstypen, Namen oder IP-Adressen. Gelöschte Cookies oder andere Geräte können erneut zählen; die Werte sind daher keine genaue Personenzahl. Das Löschen von Antworten nimmt bereits aggregierte Zählungen nicht zurück.'],
    fr:['Totaux cumulés du site','Visiteurs','Restés une minute','Visiteurs ayant terminé le test','À propos du comptage anonyme','Statistiques temporairement indisponibles','Aucun compte, nom ou e-mail requis','Cette exploration ne demande ni nom, ni e-mail, ni date de naissance et ne contient aucune publicité. Un Cookie aléatoire valable 365 jours distingue les navigateurs pour compter les visites, 60 secondes cumulées lorsque la page est visible et les explorations terminées. Chaque étape compte une seule fois par navigateur, y compris une exploration terminée avec uniquement des réponses neutres. Ce compteur ne stocke ni ne transmet de réponses, scores, types de personnalité, noms ou adresses IP. Supprimer les Cookies ou utiliser un autre appareil peut compter à nouveau : ces chiffres ne correspondent donc pas à un nombre exact de personnes. Effacer les réponses ne retire pas les totaux déjà agrégés.'],
    es:['Totales acumulados del sitio','Visitantes','Permanecieron un minuto','Visitantes que completaron el test','Sobre el recuento anónimo','Las estadísticas no están disponibles','Sin cuenta, nombre ni correo','La exploración no pide nombre, correo ni fecha de nacimiento y no contiene anuncios. Una Cookie aleatoria válida durante 365 días distingue los navegadores para contar las visitas, 60 segundos acumulados con la página visible y las exploraciones terminadas. Cada hito cuenta una vez por navegador, incluida una exploración completada con todas las respuestas neutrales. Este contador no guarda ni envía respuestas, puntuaciones, tipos de personalidad, nombres ni direcciones IP. Borrar las Cookies o usar otro dispositivo puede volver a contar, por lo que no son cifras exactas de personas. Borrar las respuestas no revierte los totales ya agregados.']
  };
  const countStarts={"zh-Hant": "統計自 2026-10-28 啟用日起累計，沒有回填過往流量。", "zh-Hans": "统计自 2026-10-28 启用日起累计，没有回填过去的流量。", "en": "Counts start from activation on 2026-10-28. Past traffic is not backfilled.", "ja": "集計は2026-10-28の開始分からです。過去の訪問数は追加していません。", "ko": "집계는 2026-10-28 시작분부터이며 이전 방문 수는 추가하지 않았습니다.", "hi": "गणना 2026-10-28 से शुरू होती है। पुराने ट्रैफ़िक को नहीं जोड़ा गया है।", "th": "เริ่มนับตั้งแต่วันที่ 2026-10-28 โดยไม่ได้เพิ่มยอดการเข้าชมในอดีต", "id": "Penghitungan dimulai pada 2026-10-28. Kunjungan sebelumnya tidak ditambahkan.", "de": "Die Zählung beginnt am 2026-10-28. Frühere Besuche werden nicht nachgetragen.", "fr": "Le comptage commence le 2026-10-28. Les visites antérieures ne sont pas ajoutées.", "es": "El recuento comienza el 2026-10-28. No se añaden visitas anteriores."};
  let totals=null,unavailable=false,visibleMs=0,anchor=null,visited=false,engaged=false,completed=false,wantsCompletion=false,visitPromise=null;
  const pending=new Set(),nextAttempt={visit:0,engaged:0,completed:0};
  function storage(){try{return global.localStorage;}catch{return null;}}
  if(eligible){try{visibleMs=Math.max(0,Math.min(31536000000,Number(storage()?.getItem(KEY))||0));}catch{}}
  function setText(node,value){if(node&&node.textContent!==value)node.textContent=value;}
  function render(){
    const code=global.GuaI18n?.locale()||doc.documentElement.lang||'zh-Hant',labels=copy[code]||copy['zh-Hant'];
    const region=doc.getElementById('traffic-counters');if(region)region.setAttribute('aria-label',labels[0]);
    ['visits','engaged','completed'].forEach((key,i)=>{setText(doc.querySelector('[data-traffic-label="'+key+'"]'),labels[i+1]);setText(doc.querySelector('[data-traffic-value="'+key+'"]'),totals?new Intl.NumberFormat(code).format(totals[key]):'—');});
    setText(doc.getElementById('traffic-note'),labels[4]);setText(doc.getElementById('traffic-status'),unavailable?labels[5]:'');
    setText(doc.querySelector('[data-traffic-privacy-title]'),labels[6]);setText(doc.querySelector('[data-traffic-privacy]'),labels[7]+' '+countStarts[code]);
  }
  function accept(payload){if(!payload?.totals||!['visits','engaged','completed'].every(key=>Number.isSafeInteger(payload.totals[key])&&payload.totals[key]>=0))throw new Error('Unavailable totals');totals=payload.totals;unavailable=false;render();return payload;}
  async function read(){try{const r=await global.fetch(endpoint,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Unavailable');accept(await r.json());}catch{unavailable=true;render();}}
  async function post(event){
    if(!eligible||pending.has(event))return null;
    pending.add(event);
    try{const body=event==='engaged'?{event,visibleMs:Math.floor(visibleMs)}:{event};const r=await global.fetch(endpoint,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error('Unavailable');const p=accept(await r.json());if(p.readOnly)return null;if(p.visitor){engaged=Boolean(p.visitor.engaged);completed=Boolean(p.visitor.completed);}if(event==='visit')visited=true;if(p.retryAfterSeconds)nextAttempt.engaged=Date.now()+p.retryAfterSeconds*1000;return p;}catch{unavailable=true;render();return null;}finally{pending.delete(event);}
  }
  const pause=ms=>new Promise(resolve=>global.setTimeout(resolve,ms));
  async function serializedVisit(){
    if(global.navigator?.locks?.request)return global.navigator.locks.request('gj-traffic-visit',()=>post('visit'));
    const store=storage();if(!store)return post('visit');
    const owner=Math.random().toString(36).slice(2)+Date.now();
    try{for(let i=0;i<60;i++){let lease;try{lease=JSON.parse(store.getItem(LOCK)||'null');}catch{}if(lease&&lease.until>Date.now()&&lease.owner!==owner){await pause(100);continue;}store.setItem(LOCK,JSON.stringify({owner,until:Date.now()+6000}));await pause(70);const won=JSON.parse(store.getItem(LOCK)||'null');if(won?.owner!==owner)continue;try{return await post('visit');}finally{const current=JSON.parse(store.getItem(LOCK)||'null');if(current?.owner===owner)store.removeItem(LOCK);}}return null;}catch{return post('visit');}
  }
  function captureTime(){const now=global.performance.now();if(anchor!==null)visibleMs=Math.min(31536000000,visibleMs+Math.max(0,now-anchor));anchor=doc.visibilityState==='visible'?now:null;if(eligible){try{storage()?.setItem(KEY,String(Math.floor(visibleMs)));}catch{}}}
  async function milestones(){
    if(!eligible)return;
    if(!visited){if(!visitPromise){if(Date.now()<nextAttempt.visit)return;nextAttempt.visit=Date.now()+30000;visitPromise=serializedVisit().finally(()=>{visitPromise=null;});}await visitPromise;if(!visited)return;}
    const now=Date.now();
    if(visibleMs>=60000&&!engaged&&!pending.has('engaged')&&now>=nextAttempt.engaged){nextAttempt.engaged=now+30000;await post('engaged');}
    if(wantsCompletion&&!completed&&!pending.has('completed')&&now>=nextAttempt.completed){nextAttempt.completed=now+30000;await post('completed');}
  }
  function inspectCompletion(){
    render();if(!/^#result\/(10|20|48)$/.test(global.location.hash))return;
    const candidate=doc.querySelector('main .uncertain-report .candidate-grid');
    const determined=doc.querySelector('main .report-shell .report-type')&&doc.querySelector('main .report-breadcrumb a[href="#home"]');
    if(candidate||determined){wantsCompletion=true;void milestones();}
  }
  function start(){render();anchor=doc.visibilityState==='visible'?global.performance.now():null;if(eligible)void milestones();else void read();const main=doc.getElementById('main');if(main)new MutationObserver(inspectCompletion).observe(main,{childList:true,subtree:true});inspectCompletion();global.addEventListener('gua:languagechange',render);doc.addEventListener('visibilitychange',()=>{captureTime();void milestones();});global.addEventListener('pagehide',captureTime);global.setInterval(()=>{captureTime();void milestones();},1000);global.setInterval(read,60000);}
  if(global.GuaI18n?.ready)global.GuaI18n.ready.then(start);else if(doc.readyState==='loading')doc.addEventListener('DOMContentLoaded',start,{once:true});else start();
})(typeof window!=='undefined'?window:globalThis);
